import{z as B,x as A,o as r,c as p,q as s,j as i,D as e,d as l,s as o,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Tail at Scale","description":"","frontmatter":{"title":"Tail at Scale","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tail-at-scale.md","filePath":"cs/tail-at-scale.md","lastUpdated":1791413859000}'),d={name:"cs/tail-at-scale.md"};function c(m,a,h,D,u,f){const E=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=s('<h1 id="tail-at-scale" tabindex="-1">Tail at Scale <a class="header-anchor" href="#tail-at-scale" aria-label="Permalink to &quot;Tail at Scale&quot;">​</a></h1><div class="epigraph"><p>规模把罕见变常见：千分之一的慢，在扇出足够大时变成每次用户请求的常态。要在每一层减尾，而不是只加速平均数。</p><footer>—— 据 Dean and Barroso, The Tail at Scale, CACM 2013 整理</footer></div><p><a href="/cs/borg-kubernetes">上一课</a>把集群调度钉成 Borg / Kubernetes。<a href="/cs/tail-latency-hedging">对冲请求</a>已用第二份换 P99。缺口是<strong>把同一篇文章读成系统设计清单</strong>：微分区、请求截止、大类隔离、队列管理，以及为何共享集群让尾更肥。本课不重写对冲算法细节。后课分布式 ID 是另一条「规模下的生成器」问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户请求 = 许多微服务 × 许多分片。尾延迟分布有长尾，最大值的期望随扇出变坏。来源：后台作业、垃圾回收、磁盘寻道、包重传、邻居干扰、慢盘。平均数优化（更好的中位数机器）不自动砍尾。</p><p>Dean–Barroso 清单：对冲/备用请求、把大作业切小（微分区）、按类隔离队列、快速失败、同步打破（不齐步）、复制选择性。缺口：只在网关对冲，底层队列仍堆着不取消的工作。</p><p><span class="marginnote">与通信课的对冲课分工：那课钉 RPC 第二份；本课钉规模为何让尾变成一等指标，以及多层对策。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SLO 用尾不用均。取消要贯穿。批处理与交互分池，接 Borg 的优先级。避免全局锁与单热分片（热键课）。测量用追踪看哪一跳贡献 P99，接三支柱。</p>',9)),(r(),i(n,null,{default:e(()=>[o(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAN%5B%22%E5%A4%A7%E6%89%87%E5%87%BA%22%5D%20--%3E%20MAX%5B%22%E5%B0%BE%E8%A2%AB%E6%94%BE%E5%A4%A7%22%5D%0A%20%20MAX%20--%3E%20HEDGE%5B%22%E5%AF%B9%E5%86%B2%20%2F%20%E6%88%AA%E6%AD%A2%22%5D%0A%20%20MAX%20--%3E%20ISO%5B%22%E9%9A%94%E7%A6%BB%E9%98%9F%E5%88%97%22%5D%0A%20%20MAX%20--%3E%20PART%5B%22%E5%BE%AE%E5%88%86%E5%8C%BA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"不要用「再买更快的 CPU」当唯一手段：共享与排队会把快机器变慢尾。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[l("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"同步：所有分片等最慢者（barrier）把尾变成和。能流式返回则流式。重试无抖动在规模下变成同步惊群。熔断保护平均数，也可能把尾变成立即错误——错误预算要算进去。",-1)),(r(),i(n,null,{default:e(()=>[o(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20USER%5B%22%E4%B8%80%E4%B8%AA%E7%94%A8%E6%88%B7%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20GW%5B%22%E7%BD%91%E5%85%B3%E5%88%86%E5%8F%91%22%5D%0A%20%20GW%20--%3E%20S1%5B%22%E5%88%86%E7%89%87%201%EF%BC%8899%25%20%E6%A6%82%E7%8E%87%E5%BF%AB%EF%BC%89%22%5D%0A%20%20GW%20--%3E%20S2%5B%22%E5%88%86%E7%89%87%202%EF%BC%8899%25%20%E6%A6%82%E7%8E%87%E5%BF%AB%EF%BC%89%22%5D%0A%20%20GW%20--%3E%20SN%5B%22...%E5%85%B1%20100%20%E4%B8%AA%E5%88%86%E7%89%87%22%5D%0A%20%20S1%20--%3E%20BAR%5B%22Barrier%EF%BC%9A%E5%85%A8%E5%88%B0%E9%BD%90%E6%89%8D%E8%BF%94%E5%9B%9E%22%5D%0A%20%20S2%20--%3E%20BAR%0A%20%20SN%20--%3E%20BAR%0A%20%20BAR%20--%3E%20SLOW%5B%22%E4%BB%BB%E4%BD%95%E4%B8%80%E4%B8%AA%E6%85%A2%EF%BC%8C%E6%95%B4%E8%AF%B7%E6%B1%82%E5%B0%B1%E6%85%A2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">数字实例：单分片 1% 概率慢、100 路扇出时，全快的概率是 \\(0.99^{100}\\approx 36.6\\%\\)，也就是说约 63% 的用户请求至少撞上一个慢分片；把单机做到 99.9%，也仍有约 9.5% 撞上——平均数再漂亮也压不住这个乘法。</span></p><p><span class="marginnote">直觉类比：barrier 同步像接力赛——团队成绩由最慢一棒决定，前几棒跑得再快也只是提前站着等；流式返回相当于先交付已完成的部分，把「等最慢」改成「来一段交一段」。</span></p><p><span class="marginnote">常见误区：初学者以为「加重试」总是提升可靠性。实际上上游刚故障时，成千上万个无抖动的重试同一秒砸回来，变成同步惊群，把短暂的尾尖放大成雪崩——重试必须配退避抖动与预算上限。</span></p><p>本课不把 CACM 文当成金融交易所低延迟设计。也不写光刻。</p><p>多租户：Borg 的 best-effort 任务会偷周期，guarantee 档减尾但降利用率。这是 PACELC 在延迟–成本上的投影，不是 CAP 分区。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给具体 P99 毫秒数当规范。后课默认：规模服务的规格写尾延迟与扇出；对策多层。分布式 ID 下一课避免中心计数器成为尾与热点。地理复制把延迟下限变成光速。</p><p>砍尾是架构税。只优化均值的报表会在扇出后说谎。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扇出把稀有慢变成用户常态。</li><li>对冲、隔离、微分区、可取消、打破屏障。</li><li>共享集群利用率与尾延迟交换。</li><li>出处：Dean and Barroso, CACM 2013。</li></ul>',10))])}const _=B(d,[["render",c]]);export{C as __pageData,_ as default};
